using System;
using System.Collections.Generic;
using System.Linq;

class Solution
{
    static Dictionary<long, int> AllSubsetXors(List<long> arr)
    {
        var res = new Dictionary<long, int> { { 0L, 0 } };
        foreach (var v in arr)
        {
            var updates = new List<(long, int)>();
            foreach (var kvp in res)
            {
                long nv = kvp.Key ^ v;
                int nc = kvp.Value + 1;
                if (!res.ContainsKey(nv) || res[nv] > nc)
                {
                    updates.Add((nv, nc));
                }
            }
            foreach (var (k, c) in updates)
            {
                if (!res.ContainsKey(k) || res[k] > c)
                    res[k] = c;
            }
        }
        return res;
    }

    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        var keys = Console.ReadLine().Split(' ').Select(long.Parse).ToList();
        long target = long.Parse(Console.ReadLine());

        int half = n / 2;
        var A = keys.Take(half).ToList();
        var B = keys.Skip(half).ToList();

        var mapA = AllSubsetXors(A);
        var mapB = AllSubsetXors(B);

        int best = -1;
        foreach (var kvp in mapA)
        {
            long need = target ^ kvp.Key;
            if (mapB.TryGetValue(need, out int cb))
            {
                int total = kvp.Value + cb;
                if (best == -1 || total < best) best = total;
            }
        }

        Console.WriteLine(best);
    }
}
